#include "window.h"
#include "soapyradio.h"
#include "nativeradio.h"
#include "radiocatalog.h"
#include <QtWidgets>
#include <QSettings>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
void Window::connectReceiver(Receiver* r){
 connect(r,&Receiver::samples,this,[this,r](QByteArray bytes){if(selectedRadio_==r||(!selectedRadio_&&r==&radio_))spectrum_->updateIq(bytes);});
 connect(r,&Receiver::frame,this,[this](pocsag::Message m,quint32 f,QString identity,QDateTime timestamp){received(std::move(m),f,identity,timestamp);});
 connect(r,&Receiver::problem,this,[this,r](QString text){technical(r->config.deviceKey+" : "+text);});
 connect(r,&Receiver::state,this,[this,r](QString text){if(selectedRadio_==r)status_->setText(text);});
 connect(r,&Receiver::tuned,this,[this,r](quint32 f,quint32 rate,quint32 bandwidth,QString identity){if(selectedRadio_==r){frequencyDisplay_->setText(QString::number(f/1e6,'f',6)+" MHz");frequencyDisplay_->setToolTip(identity);spectrum_->tuneFrequency(f);spectrum_->sampleRate=rate;spectrum_->bandwidth=bandwidth;}updatePresentationState();refreshSources();});
}
void Window::selectReceiver(Receiver* r){selectedRadio_=r;spectrum_->tuneFrequency(r->config.frequency);spectrum_->sampleRate=r->config.rate;spectrum_->bandwidth=r->config.channelBandwidth;frequencyDisplay_->setText(QString::number(r->config.frequency/1e6,'f',6)+" MHz");frequencyDisplay_->setToolTip(r->config.deviceKey);refreshSources();}
void Window::refreshSources(){if(!sourcesMenu_)return;sourcesMenu_->clear();auto add=[this](Receiver* r,QString name){auto action=sourcesMenu_->addAction(name+" — "+QString::number(r->config.frequency/1e6,'f',6)+" MHz");action->setCheckable(true);action->setChecked(selectedRadio_==r||(!selectedRadio_&&r==&radio_));connect(action,&QAction::triggered,this,[this,r]{selectReceiver(r);});};add(&radio_,"Principal");for(size_t i=0;i<extraRadios_.size();++i)add(extraRadios_[i].get(),QString("SDR %1 : ").arg(i+2)+(extraRadios_[i]->config.label.isEmpty()?extraRadios_[i]->config.deviceKey:extraRadios_[i]->config.label));}
void Window::stopReceivers(){radio_.stop();for(auto& r:extraRadios_)r->stop();updateSdrIndicator();if(status_)status_->setText("Réception arrêtée — tous les SDR");}
Receiver* Window::addReceiver(RadioConfig config){
 if(extraRadios_.size()>=8)throw std::runtime_error("Limite de huit SDR supplémentaires atteinte ; réutilisez un récepteur arrêté");
 if(config.file.isEmpty()){if(radio_.isRunning()&&radio_.config.deviceKey==config.deviceKey)throw std::runtime_error("Ce SDR est déjà utilisé par le récepteur principal");for(auto& r:extraRadios_)if(r->isRunning()&&r->config.deviceKey==config.deviceKey)throw std::runtime_error("Ce SDR est déjà en réception");}
 auto receiver=std::make_unique<Receiver>();receiver->config=std::move(config);auto r=receiver.get();connectReceiver(r);extraRadios_.push_back(std::move(receiver));r->start();refreshSources();return r;
}
void Window::additionalReceivers(){
 QDialog dialog(this);dialog.setWindowTitle("Récepteurs supplémentaires — paramètres indépendants");auto form=new QFormLayout(&dialog);auto saved=new QComboBox;saved->addItem("Nouvelle configuration");QSettings prefs(settingsFile_,QSettings::IniFormat);auto configs=QJsonDocument::fromJson(prefs.value("multi/configurations").toByteArray()).array();for(auto value:configs){auto o=value.toObject();saved->addItem(o.value("name").toString(),o);}form->addRow("Configuration mémorisée",saved);
 auto device=new QComboBox;for(auto info:Receiver::deviceInfos())if(info.usable)device->addItem(info.name,info.key);form->addRow("SDR",device);auto frequency=new QDoubleSpinBox;frequency->setRange(.001,4294.967295);frequency->setDecimals(6);frequency->setValue(frequency_->value());frequency->setSuffix(" MHz");frequency->setSingleStep(frequency_->singleStep());form->addRow("Fréquence",frequency);auto gain=new QDoubleSpinBox;gain->setRange(0,50);gain->setValue(42);form->addRow("Gain dB",gain);auto ppm=new QSpinBox;ppm->setRange(-200,200);form->addRow("PPM",ppm);auto rate=new QSpinBox;rate->setRange(48000,20000000);rate->setValue(240000);form->addRow("IQ éch/s",rate);auto bandwidth=new QSpinBox;bandwidth->setRange(0,20000000);bandwidth->setSpecialValueText("Automatique");form->addRow("Bande matérielle Hz",bandwidth);auto agc=new QCheckBox("AGC matériel");form->addRow(agc);auto antenna=new QComboBox;antenna->addItem("Automatique",QString{});form->addRow("Antenne",antenna);auto baud=new QComboBox;baud->addItems({"AUTO","512","1200","2400"});form->addRow("Débit",baud);auto info=new QLabel;info->setWordWrap(true);form->addRow(info);
 auto capabilities=[&]{auto key=device->currentData().toString();bool hack=key.startsWith("hackrf:");agc->setEnabled(!hack);ppm->setEnabled(true);gain->setEnabled(true);antenna->clear();antenna->addItem("Automatique",QString{});if(key.startsWith("soapy:")||NativeRadio::supports(key)){bool busy=radio_.isRunning()&&radio_.config.deviceKey==key;for(auto& r:extraRadios_)busy|=r->isRunning()&&r->config.deviceKey==key;if(busy){info->setText("SDR déjà actif : utilisez la liste ci-dessous pour l'arrêter avant configuration.");return;}auto c=RadioCatalog::capabilities(key);if(!c.error.isEmpty()){info->setText(c.error);return;}agc->setEnabled(c.agc);if(!c.agc)agc->setChecked(false);ppm->setEnabled(c.ppm);if(!c.ppm)ppm->setValue(0);gain->setEnabled(!c.gains.isEmpty());gain->setRange(c.gainMin,c.gainMax);for(auto name:c.antennas)antenna->addItem(name,name);bandwidth->setEnabled(c.bandwidth);if(!c.bandwidth)bandwidth->setValue(0);if(!c.rates.isEmpty())rate->setValue(int(c.rates.front()));else if(c.rateMin>0)rate->setValue(int(c.rateMin));info->setText(QString("%1 ; RX %2 à %3 MHz. Taux proposés : %4. Débits élevés : surveiller la charge CPU et les débordements.").arg(c.backend).arg(c.frequencyMin/1e6).arg(c.frequencyMax/1e6).arg([&]{QStringList values;for(double rate:c.rates)values<<QString::number(rate,'f',0);return values.join(", ");}()));}else{gain->setRange(0,hack?40:50);bandwidth->setEnabled(true);rate->setValue(hack?2000000:240000);info->setText(hack?"HackRF natif : LNA par pas de 8 dB ; VGA 20 dB par défaut. PPM corrigé par logiciel.":"RTL natif : gain supporté le plus proche ; taux et bande vérifiés à l'ouverture.");}};
 connect(device,&QComboBox::currentIndexChanged,&dialog,[&]{capabilities();});capabilities();connect(saved,&QComboBox::currentIndexChanged,&dialog,[&](int index){if(index==0)return;auto o=saved->currentData().toJsonObject();device->setCurrentIndex(device->findData(o.value("key").toString()));frequency->setValue(o.value("frequency").toDouble()/1e6);gain->setValue(o.value("gain").toDouble()/10);ppm->setValue(o.value("ppm").toInt());rate->setValue(o.value("rate").toInt());bandwidth->setValue(o.value("bandwidth").toInt());agc->setChecked(o.value("agc").toBool());antenna->setCurrentIndex(qMax(0,antenna->findData(o.value("antenna").toString())));baud->setCurrentText(o.value("baud").toString("AUTO"));});
 auto active=new QComboBox;for(size_t i=0;i<extraRadios_.size();++i)active->addItem(QString("SDR %1 — ").arg(i+2)+extraRadios_[i]->config.deviceKey,int(i));form->addRow("Sessions existantes",active);auto stop=new QPushButton("Arrêter cette session");form->addRow(stop);connect(stop,&QPushButton::clicked,&dialog,[&]{int i=active->currentData().toInt();if(active->currentIndex()>=0&&i<int(extraRadios_.size()))extraRadios_[i]->stop();updateSdrIndicator();});
 auto start=new QPushButton("Mémoriser et démarrer ce SDR");form->addRow(start);connect(start,&QPushButton::clicked,&dialog,[&]{if(device->currentIndex()<0){QMessageBox::warning(&dialog,"SDR","Aucun SDR accessible");return;}try{RadioConfig config;config.deviceKey=device->currentData().toString();config.label=device->currentText();config.frequency=quint32(qRound64(frequency->value()*1e6));config.gain=qRound(gain->value()*10);config.ppm=ppm->value();config.rate=rate->value();config.bandwidth=bandwidth->value();config.automaticGain=agc->isEnabled()&&agc->isChecked();config.antenna=antenna->currentData().toString();config.baud=baud->currentText().toInt();Receiver* r=nullptr;for(auto& existing:extraRadios_)if(!existing->isRunning()&&existing->config.deviceKey==config.deviceKey){existing->config=config;r=existing.get();r->start();break;}if(!r)r=addReceiver(config);QJsonObject o{{"name",device->currentText()+" / "+frequency->text()},{"key",config.deviceKey},{"frequency",double(config.frequency)},{"gain",config.gain},{"ppm",config.ppm},{"rate",double(config.rate)},{"bandwidth",double(config.bandwidth)},{"agc",config.automaticGain},{"antenna",config.antenna},{"baud",baud->currentText()}};if(saved->currentIndex()>0)configs[saved->currentIndex()-1]=o;else configs.append(o);prefs.setValue("multi/configurations",QJsonDocument(configs).toJson(QJsonDocument::Compact));prefs.sync();selectReceiver(r);dialog.accept();}catch(const std::exception& e){technical(QString::fromUtf8(e.what()));QMessageBox::warning(&dialog,"SDR",QString::fromUtf8(e.what()));}});
 auto close=new QDialogButtonBox(QDialogButtonBox::Close);form->addRow(close);connect(close,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);dialog.exec();
}
